		 UPDATE statistics_info


				 statistics_count = #{bean.statisticsCount},


 		 where statistics_date=#{statisticsDate} and user_id=#{userId} and data_type=#{dataType}

mapper.select:
select focus_user_id as user_id ,count(1) as statistics_count from user_focus where
 DATE_FORMAT(focus_time,'%Y-%m-%d') = #{statisticsDate} 
group by focus_user_id

select video_user_id as user_id ,count(1) as statistics_count from video_comment where
 DATE_FORMAT(post_time,'%Y-%m-%d') = #{statisticsDate} 
group by video_id,video_user_id
